// Flattens one Evinor delivery into the fields the rest of the workflow uses,
// and adds it to the daily digest buffer.
// Payload reference: https://github.com/evinor-ai/n8n-nodes-evinor
const SUBJECT_ROLE = {
  FUND_RAISING: 'COMPANY_RAISING_FUNDS',
  LEADERSHIP_CHANGE: 'COMPANY_NAME',
  LAYOFF: 'COMPANY_NAME',
};

const store = $getWorkflowStaticData('global');
store.digest = store.digest ?? [];

const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const d = e.details ?? {};
  const roles = Array.isArray(d.roles) ? d.roles : [];
  const first = (code) => roles.find((r) => r.code === code);
  const every = (code) => roles.filter((r) => r.code === code).map((r) => r.textValue);

  const eventType = e.eventCodeName ?? d.templateCodeName ?? '';
  const subject = first(SUBJECT_ROLE[eventType] ?? 'COMPANY_NAME');
  const amount = first('AMOUNT_RAISED');

  // Respect the date's precision: a MONTH (or null) precision date has no real day.
  let eventDate = '';
  if (e.eventDate?.value) {
    eventDate = e.eventDate.precision === 'DAY'
      ? e.eventDate.value.slice(0, 10)
      : e.eventDate.value.slice(0, 7);
    if (e.eventDate.source === 'ESTIMATED') eventDate += ' (estimated)';
  }

  const band = d.confidence?.band ?? 'UNKNOWN';
  const company = subject?.textValue ?? '';
  const outlets = (d.reportingOutlets ?? []).map((o) => o.name).filter(Boolean).join(', ');

  let reviewReason = '';
  if (!company) reviewReason = 'No company on the event';
  else if (band !== 'HIGH') reviewReason = `Confidence is ${band}`;

  const ev = {
    eventId: e.externalEventId ?? d.incidentId ?? '',
    eventType,
    sentence: d.generatedSentence ?? d.summaryText ?? '',
    band,
    company,
    entityId: subject?.namedEntityId ?? '',
    amount: amount?.parsedAmount ?? '',
    amountUnit: amount?.parsedAmountUnit ?? '',
    roundType: first('FUNDING_ROUND_TYPE')?.textValue ?? '',
    investors: every('INVESTING_COMPANY_NAME').join(', '),
    roleTitle: first('ROLE_TITLE')?.textValue ?? '',
    incomingPerson: first('INCOMING_PERSON')?.textValue ?? '',
    outgoingPerson: first('OUTGOING_PERSON')?.textValue ?? '',
    affectedEmployees: first('AFFECTED_EMPLOYEES_COUNT')?.textValue ?? '',
    eventDate,
    outlets,
    reportCount: d.matchingReportCount ?? 0,
    sourceKind: d.triggeringReport?.sourceKind ?? '',
    isTest: e.isTest === true,
    autoRoute: reviewReason === '',
    reviewReason,
  };

  if (!ev.isTest) {
    store.digest.push({ eventType: ev.eventType, sentence: ev.sentence, band: ev.band, outlets: ev.outlets });
    store.digest = store.digest.slice(-500);
  }
  out.push({ json: ev });
}
return out;

