// Picks the CRM company. An exact evinor_entity_id match wins; otherwise a
// single exact-name match is accepted. Anything ambiguous goes to a person.
const ev = $('Normalize event').item.json;
const results = $json.results ?? [];
const byId = ev.entityId
  ? results.filter((c) => c.properties?.evinor_entity_id === ev.entityId)
  : [];
const candidates = byId.length > 0 ? byId : results;
const company = candidates.length === 1 ? candidates[0] : null;

let route;
let reviewReason = '';
if (!company) {
  route = 'review';
  reviewReason = candidates.length === 0
    ? `No HubSpot company matched "${ev.company}"`
    : `${candidates.length} HubSpot companies are named "${ev.company}". Set evinor_entity_id = ${ev.entityId || '(none on event)'} on the right one`;
} else if (!company.properties?.hubspot_owner_id) {
  route = 'lead';
} else if (ev.eventType === 'LAYOFF') {
  route = 'review';
  reviewReason = 'Layoff at an owned account: a person decides the tone';
} else {
  route = 'task';
}

const details = [
  ev.amount !== '' ? `Amount: ${ev.amount} ${ev.amountUnit}`.trim() : '',
  ev.roundType ? `Round: ${ev.roundType}` : '',
  ev.investors ? `Investors: ${ev.investors}` : '',
  ev.incomingPerson ? `Incoming: ${ev.incomingPerson}` : '',
  ev.outgoingPerson ? `Outgoing: ${ev.outgoingPerson}` : '',
  ev.roleTitle ? `Role: ${ev.roleTitle}` : '',
  ev.eventDate ? `Event date: ${ev.eventDate}` : '',
  `Reported by: ${ev.outlets || 'unnamed outlets'} (${ev.reportCount} reports)`,
  `Evinor event: ${ev.eventId}`,
].filter(Boolean);

return {
  json: {
    ...ev,
    route,
    reviewReason,
    hubspotCompanyId: company?.id ?? '',
    ownerId: company?.properties?.hubspot_owner_id ?? '',
    matchedBy: byId.length > 0 ? 'evinor_entity_id' : 'name',
    noteHtml: `<p><strong>${ev.sentence}</strong></p><p>${details.join('<br>')}</p>`,
    taskSubject: `${ev.eventType === 'FUND_RAISING' ? 'Funding' : 'Leadership change'}: ${ev.company}`,
    taskBody: `${ev.sentence}\n${details.join('\n')}`,
  },
};

