// Builds one message from everything buffered by "Normalize event" since the
// last digest, then clears the buffer. Static data only persists for an
// active workflow (production runs), not for manual test runs.
const store = $getWorkflowStaticData('global');
const events = store.digest ?? [];
store.digest = [];
if (events.length === 0) return [];

const shown = events.slice(0, 40);
const lines = shown.map((e) => `• *${e.eventType}* ${e.sentence} _(${e.band}; ${e.outlets || 'unnamed outlets'})_`);
if (events.length > shown.length) lines.push(`…and ${events.length - shown.length} more`);
return [{ json: { text: `*Evinor: ${events.length} event(s) since the last digest*\n${lines.join('\n')}` } }];
